ALTER TABLE public.society_income_records ADD COLUMN suggested_category_id uuid, ADD COLUMN suggestion_confidence text, ADD COLUMN suggestion_explanation text, ADD COLUMN suggestion_revision uuid, ADD COLUMN suggested_at timestamptz, ADD COLUMN category_confirmed_at timestamptz, ADD COLUMN category_confirmed_by uuid, ADD COLUMN category_decision_id uuid;
ALTER TABLE public.society_income_records ADD CONSTRAINT income_suggestion_confidence_check CHECK (suggestion_confidence IS NULL OR suggestion_confidence IN ('high','medium'));
REVOKE UPDATE ON public.society_income_records FROM authenticated;
CREATE FUNCTION public.guard_income_category_review() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.verification_status <> 'pending' AND (NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.suggested_category_id IS DISTINCT FROM OLD.suggested_category_id OR NEW.suggestion_revision IS DISTINCT FROM OLD.suggestion_revision OR NEW.category_confirmed_at IS DISTINCT FROM OLD.category_confirmed_at) THEN RAISE EXCEPTION 'income_category_locked' USING ERRCODE='23514'; END IF; IF NEW.verification_status = 'verified' AND OLD.verification_status = 'pending' AND OLD.suggestion_revision IS NOT NULL AND (OLD.category_confirmed_at IS NULL OR OLD.category_confirmed_at < OLD.suggested_at) THEN RAISE EXCEPTION 'income_category_review_required' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER income_category_review_guard BEFORE UPDATE ON public.society_income_records FOR EACH ROW EXECUTE FUNCTION public.guard_income_category_review();
REVOKE ALL ON FUNCTION public.guard_income_category_review() FROM PUBLIC, anon, authenticated;
CREATE FUNCTION public.store_income_category_suggestion(_record_id uuid, _actor_id uuid, _category_id uuid, _confidence text, _explanation text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE r public.society_income_records%ROWTYPE; rev uuid; BEGIN SELECT * INTO r FROM public.society_income_records WHERE id = _record_id FOR UPDATE; IF NOT FOUND OR _actor_id IS NULL OR NOT public.is_society_admin_for(_actor_id, r.society_id) THEN RETURN jsonb_build_object('status','not_found'); END IF; IF NOT public.is_non_member_income_enabled_internal(r.society_id) THEN RETURN jsonb_build_object('status','plan_required'); END IF; IF r.verification_status <> 'pending' OR r.category_confirmed_at IS NOT NULL THEN RETURN jsonb_build_object('status','already_processed'); END IF; IF _confidence NOT IN ('high','medium') OR _explanation IS NULL OR length(_explanation) NOT BETWEEN 10 AND 220 OR NOT EXISTS (SELECT 1 FROM public.society_income_categories c WHERE c.id = _category_id AND c.society_id = r.society_id AND c.is_active) THEN RETURN jsonb_build_object('status','invalid_input'); END IF; rev := gen_random_uuid(); UPDATE public.society_income_records SET suggested_category_id = _category_id, suggestion_confidence = _confidence, suggestion_explanation = _explanation, suggestion_revision = rev, suggested_at = now() WHERE id = r.id; INSERT INTO public.audit_log(actor_id, action, target_table, target_id, society_id, metadata) VALUES (_actor_id, 'income_record.category_suggested', 'society_income_records', r.id::text, r.society_id, jsonb_build_object('category_id',_category_id,'confidence',_confidence,'revision',rev)); RETURN jsonb_build_object('status','suggested'); END $$;
REVOKE ALL ON FUNCTION public.store_income_category_suggestion(uuid,uuid,uuid,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.store_income_category_suggestion(uuid,uuid,uuid,text,text) TO service_role;
CREATE FUNCTION public.confirm_income_category(_record_id uuid, _category_id uuid, _request_id uuid, _expected_revision uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE r public.society_income_records%ROWTYPE; uid uuid := auth.uid(); BEGIN SELECT * INTO r FROM public.society_income_records WHERE id = _record_id FOR UPDATE; IF NOT FOUND OR uid IS NULL OR NOT public.is_society_admin_for(uid, r.society_id) THEN RETURN jsonb_build_object('status','not_found'); END IF; IF NOT public.is_non_member_income_enabled_internal(r.society_id) THEN RETURN jsonb_build_object('status','plan_required'); END IF; IF _request_id IS NULL OR _category_id IS NULL THEN RETURN jsonb_build_object('status','invalid_input'); END IF; IF r.category_decision_id = _request_id THEN RETURN jsonb_build_object('status',CASE WHEN r.category_id = _category_id THEN 'already_processed' ELSE 'conflict' END); END IF; IF r.verification_status <> 'pending' OR r.journal_entry_id IS NOT NULL THEN RETURN jsonb_build_object('status','invalid_transition'); END IF; IF r.suggestion_revision IS DISTINCT FROM _expected_revision THEN RETURN jsonb_build_object('status','conflict'); END IF; IF NOT EXISTS (SELECT 1 FROM public.society_income_categories c WHERE c.id = _category_id AND c.society_id = r.society_id AND c.is_active) THEN RETURN jsonb_build_object('status','category_unavailable'); END IF; UPDATE public.society_income_records SET category_id = _category_id, category_confirmed_at = now(), category_confirmed_by = uid, category_decision_id = _request_id WHERE id = r.id; INSERT INTO public.audit_log(actor_id, action, target_table, target_id, society_id, metadata) VALUES (uid, 'income_record.category_confirmed', 'society_income_records', r.id::text, r.society_id, jsonb_build_object('from_category_id',r.category_id,'to_category_id',_category_id,'suggestion_revision',r.suggestion_revision,'request_id',_request_id)); RETURN jsonb_build_object('status','success'); END $$;
REVOKE ALL ON FUNCTION public.confirm_income_category(uuid,uuid,uuid,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.confirm_income_category(uuid,uuid,uuid,uuid) TO authenticated;